#include <cstdint>
#include <cstdio>
#include <string>

std::int64_t countsToMicroseconds(std::int64_t counts, std::int64_t frequency)
{
    const std::int64_t whole{ counts / frequency }, rest{ counts % frequency };
    return whole * 1'000'000 + rest * 1'000'000 / frequency;
}

namespace
{
    constexpr std::int64_t EpochDifference{ 11'644'473'600LL };          // seconds from 1601 to 1970

    std::int64_t floorDiv(std::int64_t a, std::int64_t b) { std::int64_t q{ a / b }; if ((a % b != 0) && ((a < 0) != (b < 0))) --q; return q; }
}

std::int64_t fileTimeToUnixMs(std::uint64_t fileTime)
{
    const std::int64_t ms{ static_cast<std::int64_t>(fileTime / 10'000) };   // 100 ns -> ms, rounding down (file times are never negative)
    return ms - EpochDifference * 1000;
}

std::uint64_t unixMsToFileTime(std::int64_t unixMs)
{
    return static_cast<std::uint64_t>(unixMs + EpochDifference * 1000) * 10'000;
}

std::string formatUtc(std::uint64_t fileTime)
{
    const std::int64_t seconds{ static_cast<std::int64_t>(fileTime / 10'000'000) - EpochDifference };   // Unix seconds
    const std::int64_t days{ floorDiv(seconds, 86400) };
    const std::int64_t secOfDay{ seconds - days * 86400 };

    // Days since 1970-01-01 to a civil date (Howard Hinnant's algorithm).
    const std::int64_t z{ days + 719468 };
    const std::int64_t era{ floorDiv(z, 146097) };
    const std::int64_t doe{ z - era * 146097 };
    const std::int64_t yoe{ (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365 };
    const std::int64_t doy{ doe - (365 * yoe + yoe / 4 - yoe / 100) };
    const std::int64_t mp{ (5 * doy + 2) / 153 };
    const std::int64_t d{ doy - (153 * mp + 2) / 5 + 1 };
    const std::int64_t m{ mp < 10 ? mp + 3 : mp - 9 };
    const std::int64_t y{ yoe + era * 400 + (m <= 2 ? 1 : 0) };

    char buffer[32];
    std::snprintf(buffer, sizeof(buffer), "%04lld-%02lld-%02lld %02lld:%02lld:%02lld",
                  static_cast<long long>(y), static_cast<long long>(m), static_cast<long long>(d),
                  static_cast<long long>(secOfDay / 3600), static_cast<long long>(secOfDay / 60 % 60), static_cast<long long>(secOfDay % 60));
    return buffer;
}

unitTests:
TEST("counter to microseconds") {
    CHECK_EQ(countsToMicroseconds(10'000'000, 10'000'000), std::int64_t{ 1'000'000 }); CHECK_EQ(countsToMicroseconds(15, 10'000'000), std::int64_t{ 1 });
    CHECK_EQ(countsToMicroseconds(25'920'000'000'000LL, 10'000'000), std::int64_t{ 2'592'000'000'000LL });
    CHECK_EQ(countsToMicroseconds(10, 3), std::int64_t{ 3'333'333 });
}
TEST("FILETIME and Unix time") {
    CHECK_EQ(fileTimeToUnixMs(116'444'736'000'000'000ULL), std::int64_t{ 0 });
    CHECK_EQ(fileTimeToUnixMs(116'444'736'000'009'999ULL), std::int64_t{ 0 }); CHECK_EQ(fileTimeToUnixMs(116'444'736'000'010'000ULL), std::int64_t{ 1 });
    CHECK_EQ(unixMsToFileTime(0), 116'444'736'000'000'000ULL); CHECK_EQ(fileTimeToUnixMs(unixMsToFileTime(1'763'210'707'123LL)), std::int64_t{ 1'763'210'707'123LL });
    CHECK_EQ(fileTimeToUnixMs(0), std::int64_t{ -11'644'473'600'000LL });
}
TEST("dates") {
    CHECK_EQ(formatUtc(116'444'736'000'000'000ULL), std::string("1970-01-01 00:00:00"));
    CHECK_EQ(formatUtc(0), std::string("1601-01-01 00:00:00"));
    CHECK_EQ(formatUtc(unixMsToFileTime(951'782'400'000LL)), std::string("2000-02-29 00:00:00"));
    CHECK_EQ(formatUtc(unixMsToFileTime(1'763'213'107'000LL)), std::string("2025-11-15 13:25:07"));
    CHECK_EQ(formatUtc(unixMsToFileTime(4'107'542'399'000LL)), std::string("2100-02-28 23:59:59"));
    CHECK_EQ(formatUtc(unixMsToFileTime(4'107'542'400'000LL)), std::string("2100-03-01 00:00:00"));
}

